-- MITRC LibSphere realistic demo dataset
-- Fictional MITRC people/accounts; real published book metadata.
-- Demo password for all seeded accounts: LibSphere@2026
-- PostgreSQL pgcrypto creates bcrypt hashes at load time.

BEGIN;








-- Department relevance
SELECT b.id,d.id,CASE WHEN d.code='CSE' THEN 5 ELSE 2 END
FROM books b CROSS JOIN departments d
WHERE d.code IN ('CSE','AIDS') AND b.category_id IN ('10000000-0000-0000-0000-000000000001','10000000-0000-0000-000000000002','10000000-0000-0000-000000000003','10000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000005','10000000-0000-0000-0000-000000000006');
SELECT b.id,d.id,3 FROM books b CROSS JOIN departments d
WHERE d.code IN ('ECE','ME','CE','EE','MBA') AND b.category_id IN ('10000000-0000-0000-0000-000000000007','10000000-0000-0000-0000-000000000008');

-- Additional relevance for core CSE books
ON CONFLICT (book_id, department_id) DO UPDATE SET relevance=EXCLUDED.relevance;

-- Physical copies: 3-5 per title, 95 total
SELECT b.id,
       'MITRC-'||LPAD(ROW_NUMBER() OVER (ORDER BY b.id)::text,4,'0'),
       'LIB-'||LPAD(ROW_NUMBER() OVER (ORDER BY b.id)::text,6,'0'),
       CASE WHEN b.category_id='10000000-0000-0000-0000-000000000002' THEN 'AI-A' ELSE 'CS-'||CHR(65 + ((ROW_NUMBER() OVER (ORDER BY b.id)-1)%4)) END,
       'S-'||(((ROW_NUMBER() OVER (ORDER BY b.id)-1)%8)+1),
       'AVAILABLE','GOOD','2024-07-15'
FROM books b CROSS JOIN LATERAL generate_series(1, CASE WHEN b.id IN ('50000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000009','50000000-0000-0000-0000-000000000019') THEN 5 ELSE 3 END) g;

-- Current CSE copy statuses
UPDATE book_copies SET status='BORROWED' WHERE id IN (SELECT id FROM book_copies WHERE book_id IN ('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000009','50000000-0000-0000-0000-000000000019') ORDER BY accession_number LIMIT 5);
UPDATE book_copies SET status='RESERVED' WHERE id IN (SELECT id FROM book_copies WHERE book_id='50000000-0000-0000-0000-000000000006' ORDER BY accession_number LIMIT 2);
UPDATE book_copies SET status='DAMAGED' WHERE id IN (SELECT id FROM book_copies ORDER BY accession_number LIMIT 2);
UPDATE book_copies SET status='LOST' WHERE id IN (SELECT id FROM book_copies ORDER BY accession_number OFFSET 10 LIMIT 2);
UPDATE book_copies SET status='MAINTENANCE' WHERE id IN (SELECT id FROM book_copies ORDER BY accession_number OFFSET 20 LIMIT 2);

