-- Additional loans across other departments for comparison/data isolation.
SELECT '30000000-0000-0000-0000-000000000006', c.id, '2026-08-03','2026-08-17','2026-08-16','RETURNED','30000000-0000-0000-0000-000000000021'
FROM book_copies c WHERE c.accession_number='MITRC-0031';
