FROM book_copies c WHERE c.accession_number='MITRC-0032';

-- Keep copy statuses consistent with active loans.
UPDATE book_copies c SET status='BORROWED'
WHERE EXISTS (SELECT 1 FROM loans l WHERE l.book_copy_id=c.id AND l.returned_at IS NULL AND l.status IN ('BORROWED','OVERDUE'));
UPDATE book_copies c SET status='AVAILABLE'
WHERE c.status='BORROWED' AND NOT EXISTS (SELECT 1 FROM loans l WHERE l.book_copy_id=c.id AND l.returned_at IS NULL AND l.status IN ('BORROWED','OVERDUE'));

